import {screenshotReview} from './support-import.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function supportScreenshotHTML(photo,registry,{busy=false,icon=()=>'',role='mine'}={}){
 const p=photo?.source==='support'?photo:null,grid=p?.prepared?.grid,review=p?.rows?.length?screenshotReview(p.rows,registry):null;
 const controls=grid?`<details class="support-layout"><summary>カードの位置・列数を調整</summary><p>枠がカードと合わない場合に調整してください。範囲は画像全体に対する割合です。</p><div class="support-layout-fields"><label>横の枚数<select class="field" id="support-columns" ${busy?'disabled':''}>${[4,5,8,10].map(n=>`<option value="${n}" ${grid.columns===n?'selected':''}>${n}列 × ${40/n}行</option>`).join('')}</select></label>${[['left','左端'],['right','右端'],['top','上端'],['bottom','下端']].map(([k,label])=>`<label>${label}（%）<input class="field" id="support-${k}" type="number" min="0" max="100" step="0.1" value="${(grid.bounds[k]*100).toFixed(1)}" ${busy?'disabled':''}></label>`).join('')}</div><button class="btn full mt8" data-action="support-layout" ${busy?'disabled':''}>この配置で読み直す</button></details>`:'';
 const preview=grid?`<div class="support-preview"><img src="${esc(p.url)}" alt="読み取り元のデッキ画像"><svg viewBox="0 0 ${grid.width} ${grid.height}" aria-label="40枚の読み取り位置">${grid.cells.map(c=>`<rect x="${c.x}" y="${c.y}" width="${c.width}" height="${c.height}"/>`).join('')}</svg></div>`:p?.url?`<img class="image-preview" src="${esc(p.url)}" alt="読み取り対象のスクリーンショット">`:'';
 const rows=review?`<div class="support-review-head"><h3>読み取り結果</h3><strong class="${review.total===40?'green':''}">${review.total} / 40枚</strong></div><p class="photo-tip">${review.unresolved?'名前未確定 '+review.unresolved+'件。':''}${review.unconfirmed?'「要確認」のカードを確認してください。':'カード名と枚数を確認して登録してください。'} イラスト違いは同名でまとめます。</p><div class="support-review-list">${p.rows.map((r,i)=>{const c=registry.get(r.id);return `<article class="support-review-row ${r.confirmed?'':'uncertain'}">${r.thumbnail?`<button class="support-thumb" data-action="support-zoom" data-index="${i}" aria-label="元のカード画像を拡大"><img src="${esc(r.thumbnail)}" alt="元画像のカード ${esc(r.slots?.join('・')||i+1)}"></button>`:`<span class="support-no-image">?</span>`}<div class="support-card-copy"><span class="badge ${r.confirmed?'green':'amber'}">${r.confirmed?'読取済み':'要確認'}</span><button class="support-card-name" data-action="ocr-pick" data-index="${i}">${esc(c?.name||'カード名を選ぶ')}${icon('search',13)}</button>${r.slots?.length?`<small>画像の${r.slots.join('・')}枚目</small>`:''}${!r.confirmed&&r.candidates?.length?`<div class="support-candidates" aria-label="カード名の候補">${r.candidates.map(x=>`<button data-action="support-candidate" data-index="${i}" data-id="${esc(x.id)}">${esc(x.name)}</button>`).join('')}</div>`:''}<button class="details-link" data-action="ocr-pick" data-index="${i}">名前を検索・変更</button></div><div class="support-row-actions"><div class="stepper"><button data-action="ocr-count" data-index="${i}" data-delta="-1" ${r.count<=1?'disabled':''} aria-label="${esc(c?.name||'カード')}を1枚減らす">−</button><span>${r.count}枚</span><button data-action="ocr-count" data-index="${i}" data-delta="1" ${r.count>=40?'disabled':''} aria-label="${esc(c?.name||'カード')}を1枚増やす">＋</button></div><label class="support-check"><input type="checkbox" class="ocr-confirm" data-index="${i}" ${r.confirmed?'checked':''} ${c?'':'disabled'}>確認済み</label><button class="details-link" data-action="support-remove" data-index="${i}">削除</button></div></article>`;}).join('')}</div><button class="btn full mt16" data-action="support-add-row">${icon('plus',14)}カードを追加して修正</button><div class="support-register mt16"><p>${review.ready?'40枚のカード名・枚数を確認できました。':esc(review.errors[0])}</p>${review.unresolved?'<small>効果の対応状況はカード名の確定後に表示します。</small>':review.unsupported?`<small>効果未対応 ${review.unsupported}枚。デッキ登録・初手確認に使えます。</small>`:'<small>選択中のカードは対戦の効果に対応しています。</small>'}<button class="btn primary full mt8" data-action="support-register" ${busy||!review.ready?'disabled':''}>${icon('save',15)}この40枚を${role==='opponent'?'相手デッキ':'マイデッキ'}に登録</button><small>上のデッキ名で、この端末に保存します。</small></div>`:'';
 return `<input type="file" class="file-input" id="support-file" accept="image/png,image/jpeg,image/webp,image/*"><div class="support-intro"><span class="badge green">デュエマサポートアプリのデッキ画像</span><h3>スクショから40枚を登録</h3><p>カードが一覧になった画像を選ぶだけ。名前と枚数を読み取り、不確かなカードを修正して登録できます。</p><button class="btn ${p?'':'primary'} full mt16" data-action="choose-support" ${busy||p?.preparing?'disabled':''}>${icon('upload',16)}${p?'画像を変更する':'デッキのスクリーンショットを選ぶ'}</button><small>画像は端末内で処理し、保存・送信しません。</small></div>${preview}${p?.preparing?'<p role="status" class="photo-tip">カードの配置を調べています…</p>':''}${busy?`<div role="status" class="mt16"><h3>カード名を読み取り中…</h3><p id="support-progress">${p?.progress||0} / 40枚</p><div class="ocr-progress"><span id="support-progress-bar" style="width:${(p?.progress||0)/40*100}%"></span></div><small>初回は日本語辞書の準備に時間がかかります。</small></div>`:''}${p?.error?`<p class="error-text" role="alert">${esc(p.error)}</p>`:''}${grid&&!busy&&!review?`<p class="photo-tip">${grid.detected?'40枚の位置を検出しました。':'配置を自動で確定できませんでした。緑の枠を確認し、必要なら調整してください。'}</p><button class="btn primary full mt8" data-action="read-support">この配置で40枚を読み取る</button>`:''}${controls}${rows}`;
}
